def resolve(path, cwd, links):
    max_links = 8
    links_followed = 0

    # Start with absolute path or make it absolute using cwd
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Process components
    while remaining or current is None:
        if current is None:
            return None

        # Split off the next component
        if remaining:
            parts = remaining.split('/', 1)
            component = parts[0]
            remaining = parts[1] if len(parts) > 1 else ''
        else:
            component = ''

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current == '/':
                current = '/'
            else:
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            continue

        # Append the component
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if it's a symlink
        if candidate in links:
            links_followed += 1
            if links_followed > max_links:
                return None

            target = links[candidate]

            # Make target absolute if needed
            if target.startswith('/'):
                current = '/'
                remaining = target[1:] + ('/' + remaining if remaining else '')
            else:
                # Target is relative to the directory containing the link
                if candidate == '/':
                    link_dir = '/'
                else:
                    link_dir = candidate.rsplit('/', 1)[0]

                current = link_dir
                remaining = target + ('/' + remaining if remaining else '')
        else:
            current = candidate

    # Remove trailing slash, except for '/'
    if current and current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

